// Present existing select controls through a shared top-layer popover.
// Native controls and change handlers remain the source of truth.
export function installFilterPopovers(){
 if(window.financeFilterPopovers||!HTMLElement.prototype.showPopover)return;
 const selector=['#dashboardExpenseMonth','#cashMonthFilter','#investmentContributionFilter','#retirementHistoryType','#retirementContributionHistoryFinancialYear','#stallionContributionFinancialYear','#stallionHistoryType','#stallionHistoryFinancialYear','#reportFinancialYear','#reportType','#stallionProfitTrendFinancialYear','#surplusTrendFinancialYear','#completePortfolioSort'].join(',');
 const entries=new Map();let sequence=0,frame=0,active=null;
 function close(entry,focus=false){if(!entry)return;if(entry.panel.matches(':popover-open'))entry.panel.hidePopover();entry.trigger.setAttribute('aria-expanded','false');if(focus&&entry.trigger.isConnected)entry.trigger.focus();}
 function position(entry){const r=entry.trigger.getBoundingClientRect(),panel=entry.panel,w=Math.min(300,innerWidth-24);panel.style.width=w+'px';panel.style.maxHeight=Math.max(120,Math.min(360,innerHeight-32))+'px';const h=panel.getBoundingClientRect().height;panel.style.left=Math.max(12,Math.min(r.right-w,innerWidth-w-12))+'px';panel.style.top=Math.max(12,Math.min(r.bottom+6,innerHeight-h-12))+'px';}
 function paint(entry){const {select,trigger}=entry;trigger.hidden=select.hidden;trigger.disabled=select.disabled;const text=select.selectedOptions[0]?.textContent||'Choose';if(trigger.querySelector('span').textContent!==text)trigger.querySelector('span').textContent=text;const label=select.getAttribute('aria-label')||select.labels?.[0]?.textContent.trim()||'Filter';trigger.setAttribute('aria-label',label+': '+(select.selectedOptions[0]?.textContent||'Choose'));}
 function open(entry){close(active);active=entry;const {select,panel,trigger}=entry;const host=select.closest('dialog[open]')||document.body;if(panel.parentElement!==host)host.append(panel);panel.replaceChildren();const title=document.createElement('p');title.className='pft-filter-title';title.textContent=select.getAttribute('aria-label')||select.labels?.[0]?.textContent.trim()||'Choose filter';panel.append(title);const list=document.createElement('div');list.className='pft-filter-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',title.textContent);panel.append(list);
 const available=[...select.options];const years=[...new Set(available.map(o=>o.value.slice(0,4)))].filter(y=>/^\d{4}$/.test(y));const options=select.id==='dashboardExpenseMonth'?years.flatMap(year=>Array.from({length:12},(_,index)=>{const value=year+'-'+String(index+1).padStart(2,'0');return available.find(o=>o.value===value)||{value,textContent:new Date(value+'-01T12:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})+' · not calculated',disabled:true,selected:false};})):available;
 for(const option of options){const b=document.createElement('button');b.type='button';b.textContent=option.textContent;b.disabled=option.disabled;b.setAttribute('role','option');b.setAttribute('aria-selected',String(option.selected));b.dataset.value=option.value;b.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));paint(entry);close(entry,true);};list.append(b);}
 panel.showPopover();trigger.setAttribute('aria-expanded','true');position(entry);const selected=list.querySelector('[aria-selected=true]:not(:disabled)')||list.querySelector('button:not(:disabled)');selected?.focus({preventScroll:true});selected?.scrollIntoView({block:'nearest'});
 }
 function attach(select){if(entries.has(select))return;const trigger=document.createElement('button'),panel=document.createElement('div');trigger.type='button';trigger.className='pft-filter-trigger';trigger.id=select.id+'PopoverTrigger';trigger.innerHTML='<span></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';panel.id='pft-filter-popover-'+ ++sequence;panel.className='pft-glass-popover';panel.setAttribute('popover','auto');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',panel.id);select.after(trigger);document.body.append(panel);const entry={select,trigger,panel,oldTab:select.getAttribute('tabindex'),oldAria:select.getAttribute('aria-hidden')};entries.set(select,entry);select.classList.add('pft-native-filter');select.tabIndex=-1;select.setAttribute('aria-hidden','true');trigger.onclick=()=>panel.matches(':popover-open')?close(entry):open(entry);entry.labelHandlers=[...(select.labels||[])].map(label=>{const handler=event=>{if(event.target.closest('button'))return;event.preventDefault();trigger.focus();open(entry);};label.addEventListener('click',handler);return{label,handler};});select.addEventListener('change',()=>paint(entry));panel.addEventListener('toggle',()=>{const shown=panel.matches(':popover-open');trigger.setAttribute('aria-expanded',String(shown));if(!shown&&active===entry)active=null;});panel.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close(entry,true);return;}const buttons=[...panel.querySelectorAll('[role=option]:not(:disabled)')];let index=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:buttons.length-1))%buttons.length;buttons[index]?.focus();}else if(event.key==='Tab')close(entry);});trigger.addEventListener('keydown',event=>{if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();open(entry);}});entry.observer=new MutationObserver(()=>{paint(entry);if(active===entry)close(entry);});entry.observer.observe(select,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','hidden','selected']});paint(entry);}
 function scan(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{document.querySelectorAll(selector).forEach(attach);for(const entry of entries.values())paint(entry);});}
 const observer=new MutationObserver(scan);observer.observe(document.body,{childList:true,subtree:true});const onChange=()=>scan(),onMove=event=>{if(!active||(event.target instanceof Node&&active.panel.contains(event.target)))return;const r=active.trigger.getBoundingClientRect();if(event.type==='resize'||r.bottom<0||r.top>innerHeight)close(active);else position(active);};document.addEventListener('change',onChange);document.addEventListener('scroll',onMove,true);window.addEventListener('resize',onMove);scan();
 const reset=window.financeBridge.reset;window.financeBridge.reset=function(){observer.disconnect();cancelAnimationFrame(frame);document.removeEventListener('change',onChange);document.removeEventListener('scroll',onMove,true);window.removeEventListener('resize',onMove);for(const e of entries.values()){e.observer.disconnect();for(const {label,handler}of e.labelHandlers)label.removeEventListener('click',handler);e.trigger.remove();e.panel.remove();e.select.classList.remove('pft-native-filter');for(const [name,value]of [['tabindex',e.oldTab],['aria-hidden',e.oldAria]])value===null?e.select.removeAttribute(name):e.select.setAttribute(name,value);}delete window.financeFilterPopovers;return reset.apply(this,arguments);};window.financeFilterPopovers={refresh:scan};
}
